let estacionesMasDatos = estaciones.map(estacion => {
  let encontrada = tecnicos.find(estTemp => estTemp.codigo === estacion.CODIGO)
  if (encontrada) {
    return {
      ...estacion,
      tecnico: encontrada.tecnico,
      tipoInterno: encontrada.tipo
    }
  }

  return estacion
})

